{"modifiedFiles":[],"workingNote":"I’m inspecting the existing protocol implementation and tests to identify the state transition model, operation naming conventions, and the minimal files required for recoverFen."}{"modifiedFiles":[{"path":"src/protocol_adapter.ts","content":"export type WorldStateHandle = Record<string, string>;

export interface WorldProtocol {
  reset(): WorldStateHandle;
  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ): { success: true; newState: WorldStateHandle } | { success: false; error: string };
  getEntityState(
