  ): string;
  toAbstractSnapshot(
    state: WorldStateHandle
  ): Record<string, string>;
}

const INITIAL_STATE: WorldStateHandle = {
  Fen: "pex",
};

const cloneState = (state: WorldStateHandle): WorldStateHandle => ({
  ...state,
});

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return cloneState(INITIAL_STATE);
  },

  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ):
    | { success: true; newState: WorldStateHandle }
    | { success: false; error: string } {
    if (operationDisplayName === "advanceFen") {
      if (state.Fen !== "pex") {
        return { success: false, error: "Fen can only advance from pex" };
      }

      const newState = cloneState(state);
      newState.Fen = "dor";
      return { success: true, newState };
    }

    if (operationDisplayName === "recoverFen") {
      if (state.Fen !== "dor") {
        return { success: false, error: "Fen can only recover from dor" };
      }

      const newState = cloneState(state);
      newState.Fen = "pex";
      return { success: true, newState };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(
    state: WorldStateHandle,
    entityDisplayName: string
  ): string {
    return state[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldStateHandle): Record<string, string> {
    return cloneState(state);
  },
};
